/// Provides operations for interacting with agents using the A2A protocol.
pub fn A2AService(comptime UserDataType: type, comptime ErrorSet: type) type {
    return struct {
        pub const package = "lf.a2a.v1";
        pub const service_name = "A2AService";

        /// Sends a message to an agent.
        SendMessage: *const fn (userdata: *UserDataType, request: SendMessageRequest) ErrorSet!SendMessageResponse,
        /// Sends a streaming message to an agent, allowing for real-time interaction and status updates.
        /// Streaming version of `SendMessage`
        SendStreamingMessage: *const fn (userdata: *UserDataType, request: SendMessageRequest, writer_queue: *std.Io.Queue(StreamResponse)) ErrorSet!void,
        /// Gets the latest state of a task.
        GetTask: *const fn (userdata: *UserDataType, request: GetTaskRequest) ErrorSet!Task,
        /// Lists tasks that match the specified filter.
        ListTasks: *const fn (userdata: *UserDataType, request: ListTasksRequest) ErrorSet!ListTasksResponse,
        /// Cancels a task in progress.
        CancelTask: *const fn (userdata: *UserDataType, request: CancelTaskRequest) ErrorSet!Task,
        /// Subscribes to task updates for tasks not in a terminal state.
        /// Returns `UnsupportedOperationError` if the task is already in a terminal state (completed, failed, canceled, rejected).
        SubscribeToTask: *const fn (userdata: *UserDataType, request: SubscribeToTaskRequest, writer_queue: *std.Io.Queue(StreamResponse)) ErrorSet!void,
        /// (-- api-linter: client-libraries::4232::required-fields=disabled
        /// api-linter: core::0133::method-signature=disabled
        /// api-linter: core::0133::request-message-name=disabled
        /// aip.dev/not-precedent: method_signature preserved for backwards compatibility --)
        /// Creates a push notification config for a task.
        CreateTaskPushNotificationConfig: *const fn (userdata: *UserDataType, request: TaskPushNotificationConfig) ErrorSet!TaskPushNotificationConfig,
        /// Gets a push notification config for a task.
        GetTaskPushNotificationConfig: *const fn (userdata: *UserDataType, request: GetTaskPushNotificationConfigRequest) ErrorSet!TaskPushNotificationConfig,
        /// Get a list of push notifications configured for a task.
        ListTaskPushNotificationConfigs: *const fn (userdata: *UserDataType, request: ListTaskPushNotificationConfigsRequest) ErrorSet!ListTaskPushNotificationConfigsResponse,
        /// Gets the extended agent card for the authenticated agent.
        GetExtendedAgentCard: *const fn (userdata: *UserDataType, request: GetExtendedAgentCardRequest) ErrorSet!AgentCard,
        /// Deletes a push notification config for a task.
        DeleteTaskPushNotificationConfig: *const fn (userdata: *UserDataType, request: DeleteTaskPushNotificationConfigRequest) ErrorSet!google_protobuf.Empty,
    };
}
